SELECT (SELECT count(*) FROM Items) AS item_count, (SELECT count(*) FROM Labels) AS label_count, (SELECT count(*) FROM LabelMap) AS label_map_count, (SELECT count(*) FROM Users) AS user_count, (SELECT count(*) FROM UserGroups) AS group_count, (SELECT count(*) FROM UserGroupMembers) AS member_count, (SELECT count(*) FROM Permissions) AS permission_count, (SELECT item FROM Items WHERE itemId=4) AS wildcard_item, (SELECT label FROM Labels WHERE labelId=2) AS branch_label, (SELECT branchId FROM LabelMap WHERE itemId=3 AND labelId=2) AS mapped_branch, (SELECT password FROM Users WHERE userId=2) AS limited_password, (SELECT admin FROM Permissions WHERE userGroupId=1 AND labelId=0 AND itemId=0) AS test_admin, (SELECT itemId FROM Permissions WHERE userGroupId=2 AND labelId=2) AS limited_item;